ZONES = [
    {"id":"pile_walls","intro":n(
        "La zona occidentale concentra gli accessi e le difese più celebri della città UNESCO.",
        "The western side concentrates the UNESCO city's most famous entrances and defences.",
        "Le secteur occidental concentre les accès et défenses les plus célèbres de la ville UNESCO.",
        "La zona occidental concentra los accesos y defensas más famosos de la ciudad UNESCO."),"items":[
        item(n("Mura di Dubrovnik","Dubrovnik City Walls","Remparts de Dubrovnik","Murallas de Dubrovnik"),n("Il circuito di quasi due chilometri offre viste continue su tetti, Adriatico e forti; conviene entrare presto per evitare caldo e affollamento.","The nearly two-kilometre circuit gives continuous views over roofs, the Adriatic and forts; enter early to avoid heat and crowds.","Le circuit de près de deux kilomètres offre des vues continues sur les toits, l'Adriatique et les forts; venez tôt pour éviter chaleur et foule.","El circuito de casi dos kilómetros ofrece vistas continuas de tejados, Adriático y fortalezas; conviene entrar temprano para evitar calor y multitudes."),42.6411,18.1080,120,"fortificazione","https://dubrovnikpass.com/"),
        item(n("Porta Pile","Pile Gate","Porte Pile","Puerta de Pile"),n("Il ponte, la statua di San Biagio e il doppio sistema di porte introducono con grande efficacia alla città fortificata.","The bridge, statue of Saint Blaise and double gate system form a powerful entrance to the fortified city.","Le pont, la statue de saint Blaise et le double système de portes introduisent parfaitement la ville fortifiée.","El puente, la estatua de san Blas y el doble sistema de puertas introducen de forma espectacular la ciudad amurallada."),42.6413,18.1064,30,"porta storica",None),
        item(n("Grande Fontana di Onofrio","Large Onofrio's Fountain","Grande fontaine d'Onofrio","Gran Fuente de Onofrio"),n("La fontana poligonale del Quattrocento distribuiva l'acqua dell'acquedotto cittadino ed è ancora un punto di ritrovo molto vivo.","The fifteenth-century polygonal fountain distributed water from the city aqueduct and remains a lively meeting point.","La fontaine polygonale du XVe siècle distribuait l'eau de l'aqueduc municipal et reste un lieu de rendez-vous animé.","La fuente poligonal del siglo XV distribuía el agua del acueducto y sigue siendo un animado punto de encuentro."),42.6410,18.1072,20,"fontana",None),
        item(n("Monastero Francescano","Franciscan Monastery","Monastère franciscain","Monasterio Franciscano"),n("Chiostro romanico, biblioteca e antica farmacia raccontano la continuità religiosa e sanitaria della Repubblica di Ragusa.","Its Romanesque cloister, library and old pharmacy reveal the religious and medical continuity of the Ragusan Republic.","Cloître roman, bibliothèque et ancienne pharmacie racontent la continuité religieuse et médicale de la République de Raguse.","El claustro románico, la biblioteca y la antigua farmacia muestran la continuidad religiosa y médica de la República de Ragusa."),42.6410,18.1077,55,"monastero","https://www.dubrovnikpass.com/"),
        item(n("Forte Bokar","Bokar Fortress","Fort Bokar","Fortaleza Bokar"),n("La fortezza cilindrica proteggeva l'ingresso occidentale e permette di leggere da vicino l'ingegneria delle mura sul mare.","The cylindrical fortress protected the western entrance and reveals the engineering of the sea walls at close range.","La forteresse cylindrique protégeait l'entrée occidentale et permet d'observer de près l'ingénierie des remparts maritimes.","La fortaleza cilíndrica protegía la entrada occidental y permite observar de cerca la ingeniería de las murallas sobre el mar."),42.6395,18.1068,30,"fortezza",None),
        item(n("Forte Lovrijenac","Fort Lovrijenac","Fort Lovrijenac","Fortaleza Lovrijenac"),n("La rocca isolata si alza su una falesia di 37 metri e offre la prospettiva migliore sulle mura occidentali e sulla baia.","The detached fort rises on a 37-metre cliff and gives the best perspective over the western walls and bay.","La forteresse isolée domine une falaise de 37 mètres et offre la meilleure vue sur les remparts occidentaux et la baie.","La fortaleza aislada se alza sobre un acantilado de 37 metros y ofrece la mejor perspectiva de las murallas occidentales y la bahía."),42.6400,18.1044,60,"fortezza","https://dubrovnikpass.com/"),
    ]},
    {"id":"stradun_civic","intro":n("Il cuore civico mostra la ricchezza e l'autonomia dell'antica Repubblica di Ragusa.","The civic heart displays the wealth and autonomy of the former Republic of Ragusa.","Le cœur civique illustre la richesse et l'autonomie de l'ancienne République de Raguse.","El corazón cívico muestra la riqueza y autonomía de la antigua República de Ragusa."),"items":[
        item(n("Stradun","Stradun","Stradun","Stradun"),n("La via lastricata in pietra calcarea collega le due porte principali e diventa particolarmente suggestiva al mattino presto o la sera.","The limestone-paved street links the two main gates and is especially atmospheric early in the morning or at night.","Cette rue pavée de calcaire relie les deux portes principales et devient particulièrement évocatrice tôt le matin ou le soir.","La calle pavimentada con piedra caliza conecta las dos puertas principales y resulta especialmente evocadora temprano o por la noche."),42.6405,18.1092,35,"strada storica",None),
        item(n("Palazzo del Rettore","Rector's Palace","Palais du Recteur","Palacio del Rector"),n("Il palazzo mescola gotico e Rinascimento e conserva gli ambienti del governo, le prigioni e il Museo di Storia Culturale.","The palace blends Gothic and Renaissance architecture and preserves government rooms, prisons and the Cultural History Museum.","Le palais mêle gothique et Renaissance et conserve salles du gouvernement, prisons et musée d'Histoire culturelle.","El palacio combina gótico y Renacimiento y conserva salas de gobierno, prisiones y el Museo de Historia Cultural."),42.6400,18.1106,75,"museo","https://www.dubrovnikpass.com/"),
        item(n("Palazzo Sponza","Sponza Palace","Palais Sponza","Palacio Sponza"),n("Dogana, zecca e centro commerciale convivevano in questo elegante edificio, oggi sede dell'Archivio di Stato.","Customs, mint and trade functions once shared this elegant building, now home to the State Archives.","Douane, monnaie et commerce cohabitaient dans cet élégant édifice, aujourd'hui siège des Archives d'État.","Aduana, ceca y comercio convivían en este elegante edificio, hoy sede del Archivo Estatal."),42.6404,18.1106,35,"palazzo storico",None),
        item(n("Colonna di Orlando","Orlando's Column","Colonne d'Orlando","Columna de Orlando"),n("Il cavaliere scolpito simboleggiava libertà e giustizia; il suo avambraccio serviva anche come unità di misura ufficiale.","The carved knight symbolised freedom and justice; his forearm also served as an official unit of length.","Le chevalier sculpté symbolisait liberté et justice; son avant-bras servait aussi d'unité de mesure officielle.","El caballero esculpido simbolizaba libertad y justicia; su antebrazo también servía como unidad de medida oficial."),42.6403,18.1104,15,"monumento",None),
        item(n("Chiesa di San Biagio","Church of Saint Blaise","Église Saint-Blaise","Iglesia de San Blas"),n("La chiesa barocca custodisce la statua d'argento del patrono con un prezioso modello della città precedente al terremoto.","The Baroque church keeps a silver statue of the patron holding a precious model of the city before the earthquake.","L'église baroque conserve une statue d'argent du patron tenant un précieux modèle de la ville avant le séisme.","La iglesia barroca guarda una estatua de plata del patrón con una valiosa maqueta de la ciudad anterior al terremoto."),42.6402,18.1103,30,"chiesa",None),
        item(n("Torre dell'Orologio e Luža","Clock Tower and Luža Square","Tour de l'Horloge et place Luža","Torre del Reloj y plaza Luža"),n("I bronzi Maro e Baro scandiscono le ore sopra la piazza che ancora oggi concentra cerimonie e vita cittadina.","The bronze figures Maro and Baro strike the hours above a square that still hosts ceremonies and city life.","Les bronzes Maro et Baro sonnent les heures au-dessus d'une place toujours au cœur des cérémonies et de la vie urbaine.","Las figuras de bronce Maro y Baro marcan las horas sobre una plaza que todavía concentra ceremonias y vida urbana."),42.6403,18.1108,20,"torre",None),
    ]},
    {"id":"cathedral_jesuits","intro":n("La parte meridionale del centro storico riunisce arte sacra, mercati e memoria quotidiana.","The southern old town brings together sacred art, markets and everyday memory.","La partie sud de la vieille ville réunit art sacré, marchés et mémoire quotidienne.","La parte sur del casco antiguo reúne arte sacro, mercados y memoria cotidiana."),"items":[
        item(n("Cattedrale dell'Assunzione","Dubrovnik Cathedral","Cathédrale de l'Assomption","Catedral de la Asunción"),n("La cattedrale barocca sorge su edifici precedenti e il tesoro conserva reliquiari legati alla storia religiosa della città.","The Baroque cathedral stands over earlier churches and its treasury preserves reliquaries tied to the city's religious history.","La cathédrale baroque repose sur des édifices antérieurs et son trésor conserve des reliquaires liés à l'histoire religieuse de la ville.","La catedral barroca se levanta sobre iglesias anteriores y su tesoro conserva relicarios vinculados a la historia religiosa de la ciudad."),42.6396,18.1106,50,"chiesa",None),
        item(n("Scalinata dei Gesuiti","Jesuit Stairs","Escalier des Jésuites","Escalinata de los Jesuitas"),n("La scenografica scalinata barocca sale verso Sant'Ignazio e regala una delle prospettive urbane più riconoscibili di Dubrovnik.","The theatrical Baroque staircase climbs to Saint Ignatius and creates one of Dubrovnik's most recognisable urban views.","Le spectaculaire escalier baroque monte vers Saint-Ignace et offre l'une des perspectives urbaines les plus reconnaissables de Dubrovnik.","La escenográfica escalera barroca sube hacia San Ignacio y ofrece una de las perspectivas urbanas más reconocibles de Dubrovnik."),42.6386,18.1093,25,"scalinata",None),
        item(n("Chiesa di Sant'Ignazio","Church of Saint Ignatius","Église Saint-Ignace","Iglesia de San Ignacio"),n("Affreschi illusionistici e architettura barocca completano il complesso dell'antico collegio gesuita.","Illusionistic frescoes and Baroque architecture complete the former Jesuit college complex.","Fresques illusionnistes et architecture baroque complètent l'ensemble de l'ancien collège jésuite.","Frescos ilusionistas y arquitectura barroca completan el conjunto del antiguo colegio jesuita."),42.6384,18.1094,35,"chiesa",None),
        item(n("Piazza Gundulić","Gundulić Square","Place Gundulić","Plaza Gundulić"),n("Il mercato mattutino di frutta, erbe e prodotti locali anima la piazza dominata dal monumento al poeta Ivan Gundulić.","A morning market of fruit, herbs and local produce animates the square beneath poet Ivan Gundulić's monument.","Le marché matinal de fruits, herbes et produits locaux anime la place dominée par le monument au poète Ivan Gundulić.","El mercado matinal de fruta, hierbas y productos locales anima la plaza presidida por el monumento al poeta Ivan Gundulić."),42.6393,18.1098,35,"mercato",None),
        item(n("Museo Etnografico Rupe","Rupe Ethnographic Museum","Musée ethnographique Rupe","Museo Etnográfico Rupe"),n("Gli antichi granai scavati nella roccia ospitano costumi, tessuti e strumenti della vita rurale del territorio raguseo.","Former granaries cut into rock display costumes, textiles and tools from rural life around Ragusa.","D'anciens greniers creusés dans la roche présentent costumes, textiles et outils de la vie rurale ragusaine.","Antiguos graneros excavados en la roca muestran trajes, tejidos y herramientas de la vida rural de Ragusa."),42.6392,18.1074,60,"museo","https://www.dubrovnikpass.com/"),
        item(n("Casa di Marin Držić","Marin Držić House","Maison de Marin Držić","Casa de Marin Držić"),n("Il piccolo museo introduce al maggiore commediografo rinascimentale di Dubrovnik attraverso manoscritti, scenografie e installazioni.","The small museum introduces Dubrovnik's leading Renaissance playwright through manuscripts, stage designs and installations.","Ce petit musée présente le grand dramaturge renaissant de Dubrovnik à travers manuscrits, décors et installations.","El pequeño museo presenta al principal dramaturgo renacentista de Dubrovnik mediante manuscritos, escenografías e instalaciones."),42.6400,18.1083,50,"museo","https://www.dubrovnikpass.com/"),
    ]},
    {"id":"ploce_east","intro":n("Il lato orientale lega fortificazioni, quarantena storica e spiagge vicine alle mura.","The eastern side links fortifications, historic quarantine buildings and beaches beside the walls.","Le côté oriental relie fortifications, anciens bâtiments de quarantaine et plages au pied des remparts.","El lado oriental conecta fortificaciones, edificios históricos de cuarentena y playas junto a las murallas."),"items":[
        item(n("Porta Ploče","Ploče Gate","Porte Ploče","Puerta de Ploče"),n("Ponti e passaggi fortificati formano l'ingresso orientale, con una notevole vista sul porto vecchio.","Bridges and fortified passages form the eastern entrance, with a fine view over the Old Port.","Ponts et passages fortifiés forment l'entrée orientale, avec une belle vue sur le Vieux-Port.","Puentes y pasos fortificados forman la entrada oriental, con una magnífica vista del Puerto Viejo."),42.6414,18.1123,25,"porta storica",None),
        item(n("Forte Revelin","Revelin Fortress","Fort Revelin","Fortaleza Revelin"),n("La grande fortezza cinquecentesca difendeva porto e città; terrazze e interni ospitano oggi eventi culturali.","The great sixteenth-century fortress defended harbour and city; its terraces and interiors now host cultural events.","La grande forteresse du XVIe siècle défendait port et ville; terrasses et intérieurs accueillent aujourd'hui des événements culturels.","La gran fortaleza del siglo XVI defendía puerto y ciudad; sus terrazas e interiores acogen hoy eventos culturales."),42.6418,18.1122,40,"fortezza",None),
        item(n("Monastero Domenicano","Dominican Monastery","Monastère dominicain","Monasterio Dominico"),n("Il chiostro gotico e la collezione d'arte sacra creano una pausa silenziosa appena oltre la porta orientale.","The Gothic cloister and sacred-art collection provide a quiet pause just inside the eastern gate.","Le cloître gothique et la collection d'art sacré offrent une pause silencieuse juste après la porte orientale.","El claustro gótico y la colección de arte sacro ofrecen una pausa tranquila junto a la puerta oriental."),42.6410,18.1115,60,"monastero","https://www.dubrovnikpass.com/"),
        item(n("Lazareti","Lazareti","Lazareti","Lazareti"),n("Le dieci navate della quarantena portuale ricordano quanto la Repubblica controllasse commerci ed epidemie già dal Trecento.","The ten halls of the port quarantine recall how the Republic controlled trade and epidemics from the fourteenth century.","Les dix halles de la quarantaine portuaire rappellent comment la République contrôlait commerce et épidémies dès le XIVe siècle.","Las diez naves de la cuarentena portuaria recuerdan cómo la República controlaba comercio y epidemias desde el siglo XIV."),42.6415,18.1132,40,"sito storico",None),
        item(n("Spiaggia Banje","Banje Beach","Plage de Banje","Playa de Banje"),n("La spiaggia più vicina al centro offre il classico panorama delle mura e di Lokrum, ma in estate è molto frequentata.","The closest beach to the old town offers the classic walls-and-Lokrum panorama but becomes very busy in summer.","La plage la plus proche du centre offre le panorama classique sur les remparts et Lokrum, mais elle est très fréquentée en été.","La playa más cercana al centro ofrece la vista clásica de las murallas y Lokrum, aunque en verano está muy concurrida."),42.6413,18.1152,70,"spiaggia",None),
        item(n("Museo d'Arte Moderna di Dubrovnik","Museum of Modern Art Dubrovnik","Musée d'Art moderne de Dubrovnik","Museo de Arte Moderno de Dubrovnik"),n("La villa affacciata sul mare presenta artisti croati moderni e contemporanei insieme a terrazze panoramiche poco affollate.","The sea-facing villa presents modern and contemporary Croatian artists alongside quiet panoramic terraces.","La villa face à la mer présente des artistes croates modernes et contemporains et des terrasses panoramiques paisibles.","La villa frente al mar presenta artistas croatas modernos y contemporáneos junto a tranquilas terrazas panorámicas."),42.6413,18.1175,70,"museo","https://ugdubrovnik.hr/en/"),
    ]},
    {"id":"old_port","intro":n("Il porto vecchio racconta la potenza marittima di Ragusa e il rapporto quotidiano con l'Adriatico.","The Old Port tells the story of Ragusa's maritime power and daily relationship with the Adriatic.","Le Vieux-Port raconte la puissance maritime de Raguse et son rapport quotidien à l'Adriatique.","El Puerto Viejo cuenta el poder marítimo de Ragusa y su relación cotidiana con el Adriático."),"items":[
        item(n("Porto Vecchio","Old Port","Vieux-Port","Puerto Viejo"),n("Barche locali, traghetti e facciate fortificate rendono questo bacino uno dei punti migliori per osservare la città in movimento.","Local boats, ferries and fortified façades make this basin one of the best places to watch the city in motion.","Bateaux locaux, ferries et façades fortifiées font de ce bassin l'un des meilleurs lieux pour observer la ville en mouvement.","Barcos locales, ferris y fachadas fortificadas convierten esta dársena en uno de los mejores lugares para observar la ciudad en movimiento."),42.6401,18.1122,40,"porto",None),
        item(n("Passeggiata di Porporela","Porporela Breakwater","Jetée de Porporela","Espigón de Porporela"),n("Il breve molo oltre San Giovanni offre aria marina e una visuale ravvicinata sulle mura meridionali.","The short pier beyond Saint John brings sea air and a close view of the southern walls.","La courte jetée au-delà de Saint-Jean offre air marin et vue rapprochée sur les remparts méridionaux.","El corto muelle más allá de San Juan ofrece aire marino y una vista cercana de las murallas del sur."),42.6385,18.1132,35,"passeggiata",None),
        item(n("Museo Marittimo","Maritime Museum","Musée maritime","Museo Marítimo"),n("Modelli navali, carte e strumenti spiegano la flotta mercantile che rese Ragusa una potenza diplomatica del Mediterraneo.","Ship models, charts and instruments explain the merchant fleet that made Ragusa a Mediterranean diplomatic power.","Maquettes, cartes et instruments expliquent la flotte marchande qui fit de Raguse une puissance diplomatique méditerranéenne.","Maquetas, cartas e instrumentos explican la flota mercante que convirtió Ragusa en una potencia diplomática mediterránea."),42.6390,18.1122,60,"museo","https://www.dubrovnikpass.com/"),
        item(n("Acquario di Dubrovnik","Dubrovnik Aquarium","Aquarium de Dubrovnik","Acuario de Dubrovnik"),n("Vasche nelle volte di Forte San Giovanni presentano fauna dell'Adriatico e offrono una visita breve adatta anche alla pioggia.","Tanks beneath Saint John Fortress present Adriatic fauna and provide a short visit suitable for rainy weather.","Les bassins sous le fort Saint-Jean présentent la faune adriatique et offrent une courte visite adaptée à la pluie.","Los acuarios bajo la Fortaleza de San Juan presentan fauna del Adriático y ofrecen una visita breve adecuada para días de lluvia."),42.6391,18.1124,50,"acquario","https://www.imp-du.com/en/"),
        item(n("Forte San Giovanni","Saint John Fortress","Fort Saint-Jean","Fortaleza de San Juan"),n("La massa fortificata chiude l'ingresso del porto e ospita insieme Museo Marittimo e Acquario.","The massive fort closes the harbour entrance and houses both the Maritime Museum and Aquarium.","La puissante forteresse ferme l'entrée du port et abrite à la fois musée maritime et aquarium.","La gran fortaleza cierra la entrada del puerto y alberga el Museo Marítimo y el Acuario."),42.6391,18.1125,30,"fortezza",None),
        item(n("Giro panoramico in barca delle mura","City Walls Panoramic Boat Ride","Tour panoramique des remparts en bateau","Paseo panorámico en barco por las murallas"),n("Una breve navigazione dal porto mostra bastioni e falesie dalla prospettiva per cui furono progettati; condizioni e orari dipendono dal mare.","A short trip from the harbour shows bastions and cliffs from the perspective for which they were designed; schedules depend on sea conditions.","Une courte navigation depuis le port montre bastions et falaises depuis leur perspective maritime; horaires et départs dépendent de la mer.","Una breve navegación desde el puerto muestra bastiones y acantilados desde su perspectiva marítima; horarios y salidas dependen del estado del mar."),42.6397,18.1128,50,"escursione in barca",None),
    ]},
    {"id":"lokrum","intro":n("Lokrum è una riserva insulare raggiungibile stagionalmente in traghetto dal porto vecchio.","Lokrum is an island reserve reached seasonally by ferry from the Old Port.","Lokrum est une réserve insulaire accessible en saison par ferry depuis le Vieux-Port.","Lokrum es una reserva insular accesible en temporada por ferri desde el Puerto Viejo."),"items":[
        item(n("Riserva naturale di Lokrum","Lokrum Nature Reserve","Réserve naturelle de Lokrum","Reserva natural de Lokrum"),n("Sentieri ombreggiati, costa rocciosa e pavoni liberi rendono l'isola una pausa verde, senza pernottamenti né auto.","Shaded paths, rocky shores and free-roaming peacocks make the car-free island a green retreat with no overnight stays.","Sentiers ombragés, côtes rocheuses et paons en liberté font de l'île sans voitures une parenthèse verte sans hébergement.","Senderos sombreados, costa rocosa y pavos reales en libertad convierten la isla sin coches en una pausa verde sin alojamiento."),42.6278,18.1198,120,"riserva naturale","https://www.lokrum.hr/eng/"),
        item(n("Monastero Benedettino di Lokrum","Lokrum Benedictine Monastery","Monastère bénédictin de Lokrum","Monasterio Benedictino de Lokrum"),n("Rovine medievali e residenza asburgica testimoniano i diversi usi dell'isola nel corso dei secoli.","Medieval ruins and a Habsburg residence reveal the island's changing uses through the centuries.","Ruines médiévales et résidence habsbourgeoise témoignent des différents usages de l'île au fil des siècles.","Ruinas medievales y una residencia de los Habsburgo muestran los distintos usos de la isla a lo largo de los siglos."),42.6273,18.1203,50,"monastero",None),
        item(n("Mar Morto di Lokrum","Lokrum Dead Sea","Mer Morte de Lokrum","Mar Muerto de Lokrum"),n("Il piccolo lago salato collegato al mare offre un bagno riparato, pur restando profondo e privo di sorveglianza costante.","The small salt lake connected to the sea offers sheltered swimming, though it is deep and not constantly supervised.","Le petit lac salé relié à la mer permet une baignade abritée, mais il est profond et sans surveillance constante.","El pequeño lago salado conectado al mar ofrece un baño resguardado, aunque es profundo y no tiene vigilancia constante."),42.6258,18.1211,55,"lago salato",None),
        item(n("Forte Royal","Fort Royal","Fort Royal","Fort Royal"),n("La salita al forte napoleonico è breve ma ripida e si conclude con una vista completa su Dubrovnik e sull'arcipelago.","The climb to the Napoleonic fort is short but steep and ends with a complete view of Dubrovnik and the archipelago.","La montée vers le fort napoléonien est courte mais raide et se termine par une vue complète sur Dubrovnik et l'archipel.","La subida al fuerte napoleónico es corta pero empinada y termina con una vista completa de Dubrovnik y el archipiélago."),42.6297,18.1175,50,"fortezza",None),
        item(n("Giardino Botanico di Lokrum","Lokrum Botanical Garden","Jardin botanique de Lokrum","Jardín Botánico de Lokrum"),n("Specie mediterranee ed esotiche crescono in un giardino avviato nell'Ottocento e più volte danneggiato e restaurato.","Mediterranean and exotic species grow in a garden begun in the nineteenth century and repeatedly damaged and restored.","Des espèces méditerranéennes et exotiques poussent dans un jardin créé au XIXe siècle, plusieurs fois endommagé puis restauré.","Especies mediterráneas y exóticas crecen en un jardín iniciado en el siglo XIX, varias veces dañado y restaurado."),42.6280,18.1205,45,"giardino botanico",None),
        item(n("Scogliere e punto panoramico di Lokrum","Lokrum Cliffs and Viewpoint","Falaises et belvédère de Lokrum","Acantilados y mirador de Lokrum"),n("Le rocce sul lato aperto mostrano la forza dell'Adriatico; è necessario restare nei punti consentiti con mare mosso.","Rocks on the exposed side show the Adriatic's force; stay within permitted areas when the sea is rough.","Les rochers du côté exposé montrent la force de l'Adriatique; restez dans les zones autorisées lorsque la mer est agitée.","Las rocas del lado expuesto muestran la fuerza del Adriático; hay que permanecer en las zonas permitidas cuando el mar está agitado."),42.6248,18.1190,35,"panorama",None),
    ]},
    {"id":"srd_gruz","intro":n("Le alture e il porto moderno ampliano la visita oltre l'immagine medievale del centro.","The heights and modern harbour extend the visit beyond the old town's medieval image.","Les hauteurs et le port moderne prolongent la visite au-delà de l'image médiévale du centre.","Las alturas y el puerto moderno amplían la visita más allá de la imagen medieval del centro."),"items":[
        item(n("Funivia del Monte Srđ","Mount Srđ Cable Car","Téléphérique du mont Srđ","Teleférico del monte Srđ"),n("La funivia sale rapidamente dal quartiere Ploče al crinale; vento forte può interrompere il servizio senza molto preavviso.","The cable car climbs quickly from Ploče to the ridge; strong winds can suspend service at short notice.","Le téléphérique monte rapidement de Ploče à la crête; les vents forts peuvent interrompre le service sans grand préavis.","El teleférico sube rápidamente desde Ploče hasta la cima; el viento fuerte puede suspender el servicio con poca antelación."),42.6428,18.1100,45,"funivia","https://www.dubrovnikcablecar.com/"),
        item(n("Panorama dal Monte Srđ","Mount Srđ Viewpoint","Belvédère du mont Srđ","Mirador del monte Srđ"),n("Dalla terrazza si leggono insieme città murata, Lokrum, Elafiti e profilo costiero, soprattutto con luce del tardo pomeriggio.","The terrace brings the walled city, Lokrum, Elaphiti islands and coast into one view, especially in late-afternoon light.","La terrasse réunit ville fortifiée, Lokrum, îles Élaphites et côte dans un même panorama, surtout en fin d'après-midi.","La terraza reúne en una sola vista la ciudad amurallada, Lokrum, las Elafitas y la costa, especialmente al final de la tarde."),42.6494,18.1117,50,"panorama",None),
        item(n("Forte Imperiale","Fort Imperial","Fort Impérial","Fuerte Imperial"),n("La fortezza napoleonica domina il crinale e porta ancora i segni dell'assedio del 1991.","The Napoleonic fort dominates the ridge and still bears traces of the 1991 siege.","La forteresse napoléonienne domine la crête et porte encore les traces du siège de 1991.","La fortaleza napoleónica domina la cima y todavía conserva huellas del asedio de 1991."),42.6500,18.1114,35,"fortezza",None),
        item(n("Museo della Guerra d'Indipendenza Croata","Homeland War Museum","Musée de la guerre d'indépendance croate","Museo de la Guerra de Independencia Croata"),n("Fotografie, documenti e oggetti dentro Forte Imperiale spiegano l'assedio di Dubrovnik con un taglio locale diretto.","Photographs, documents and objects inside Fort Imperial explain the siege of Dubrovnik from a direct local perspective.","Photographies, documents et objets dans le fort Impérial expliquent le siège de Dubrovnik selon un point de vue local direct.","Fotografías, documentos y objetos dentro del Fuerte Imperial explican el asedio de Dubrovnik desde una perspectiva local directa."),42.6499,18.1115,70,"museo",None),
        item(n("Mercato di Gruž","Gruž Market","Marché de Gruž","Mercado de Gruž"),n("Il mercato mattutino vicino al porto offre pesce, frutta e prodotti della campagna in un contesto molto meno turistico.","The morning market near the harbour offers fish, fruit and countryside produce in a much less touristy setting.","Le marché matinal près du port propose poisson, fruits et produits ruraux dans un cadre bien moins touristique.","El mercado matinal junto al puerto ofrece pescado, fruta y productos del campo en un ambiente mucho menos turístico."),42.6587,18.0866,40,"mercato",None),
        item(n("Red History Museum","Red History Museum","Red History Museum","Red History Museum"),n("Oggetti e ambienti interattivi raccontano la vita quotidiana nella Jugoslavia socialista, completando la storia più antica della città.","Objects and interactive rooms explore everyday life in socialist Yugoslavia, complementing the city's older history.","Objets et salles interactives racontent la vie quotidienne dans la Yougoslavie socialiste, en complément de l'histoire ancienne de la ville.","Objetos y salas interactivas explican la vida cotidiana en la Yugoslavia socialista, complementando la historia antigua de la ciudad."),42.6593,18.0860,70,"museo","https://www.redhistorymuseum.com/"),
    ]},
    {"id":"lapad_coast","intro":n("Lapad e Babin Kuk offrono passeggiate costiere, spiagge e un ritmo più residenziale.","Lapad and Babin Kuk offer coastal walks, beaches and a more residential rhythm.","Lapad et Babin Kuk offrent promenades côtières, plages et rythme plus résidentiel.","Lapad y Babin Kuk ofrecen paseos costeros, playas y un ritmo más residencial."),"items":[
        item(n("Passeggiata di Lapad","Lapad Promenade","Promenade de Lapad","Paseo de Lapad"),n("La fascia pedonale collega caffè, vegetazione e baie ed è piacevole soprattutto nelle ore serali.","The pedestrian strip links cafés, greenery and coves and is particularly pleasant in the evening.","La zone piétonne relie cafés, végétation et criques et devient particulièrement agréable en soirée.","La zona peatonal conecta cafeterías, vegetación y calas y resulta especialmente agradable al atardecer."),42.6550,18.0725,55,"passeggiata",None),
        item(n("Baia di Lapad","Lapad Bay","Baie de Lapad","Bahía de Lapad"),n("La baia riparata combina spiaggia urbana e servizi, con accesso più semplice rispetto alle calette rocciose.","The sheltered bay combines an urban beach with services and easier access than the rocky coves.","La baie abritée combine plage urbaine et services, avec un accès plus simple que les criques rocheuses.","La bahía protegida combina playa urbana y servicios, con acceso más sencillo que las calas rocosas."),42.6554,18.0685,75,"spiaggia",None),
        item(n("Spiaggia Copacabana","Copacabana Beach Dubrovnik","Plage Copacabana de Dubrovnik","Playa Copacabana de Dubrovnik"),n("La spiaggia di Babin Kuk guarda il ponte e le Elafiti e dispone di servizi, sport acquatici e accesso graduale al mare.","The Babin Kuk beach faces the bridge and Elaphiti islands and offers facilities, water sports and gradual sea access.","La plage de Babin Kuk fait face au pont et aux Élaphites et propose services, sports nautiques et accès progressif à la mer.","La playa de Babin Kuk mira al puente y las Elafitas y ofrece servicios, deportes acuáticos y acceso gradual al mar."),42.6625,18.0586,75,"spiaggia",None),
        item(n("Sentiero di Velika e Mala Petka","Velika and Mala Petka Trail","Sentier de Velika et Mala Petka","Sendero de Velika y Mala Petka"),n("La riserva forestale offre sentieri ombreggiati e punti sul mare, ma richiede scarpe adatte e acqua nelle giornate calde.","The forest reserve offers shaded trails and sea viewpoints but requires suitable shoes and water on hot days.","La réserve forestière offre sentiers ombragés et vues marines, mais exige de bonnes chaussures et de l'eau par temps chaud.","La reserva forestal ofrece senderos sombreados y miradores al mar, pero requiere calzado adecuado y agua en días calurosos."),42.6495,18.0675,90,"sentiero",None),
        item(n("Parco Velika Petka","Velika Petka Forest Park","Parc forestier Velika Petka","Parque forestal Velika Petka"),n("Pini e macchia mediterranea creano una pausa naturale a pochi minuti dalle strutture turistiche di Lapad.","Pines and Mediterranean scrub create a natural retreat only minutes from Lapad's visitor facilities.","Pins et maquis méditerranéen créent une parenthèse naturelle à quelques minutes des installations touristiques de Lapad.","Pinos y matorral mediterráneo crean una pausa natural a pocos minutos de las instalaciones turísticas de Lapad."),42.6505,18.0700,45,"parco",None),
        item(n("Ponte Franjo Tuđman e belvedere","Franjo Tuđman Bridge Viewpoint","Belvédère du pont Franjo Tuđman","Mirador del puente Franjo Tuđman"),n("Il belvedere sopra Gruž consente di capire la geografia del porto moderno, della Rijeka Dubrovačka e delle penisole occidentali.","The viewpoint above Gruž clarifies the geography of the modern harbour, Rijeka Dubrovačka and western peninsulas.","Le belvédère au-dessus de Gruž permet de comprendre la géographie du port moderne, de la Rijeka Dubrovačka et des péninsules occidentales.","El mirador sobre Gruž permite comprender la geografía del puerto moderno, la Rijeka Dubrovačka y las penínsulas occidentales."),42.6685,18.0800,35,"panorama",None),
    ]},
]

