FOODS_BY_CITY = [
 {"name":"Crni rižot","name_en":"Black Risotto","name_fr":"Risotto noir","name_es":"Risotto negro","description":"Riso tostato e cotto con seppia, vino e brodo di mare, colorato naturalmente dal nero del mollusco. Un buon crni rižot deve essere cremoso, iodato ma non aggressivo, con la seppia ancora tenera.","description_en":"Rice is toasted and cooked with cuttlefish, wine and seafood stock, naturally coloured by its ink. A good crni rižot should be creamy and briny without becoming harsh, with tender cuttlefish.","description_fr":"Le riz est nacré puis cuit avec seiche, vin et bouillon marin, naturellement coloré par l'encre. Un bon crni rižot doit être crémeux et iodé sans agressivité, avec une seiche encore tendre.","description_es":"El arroz se tuesta y cuece con sepia, vino y caldo de mar, teñido de forma natural por su tinta. Un buen crni rižot debe ser cremoso y marino sin resultar fuerte, con la sepia todavía tierna.","ingredients":["riso","seppia","nero di seppia","vino bianco","brodo di pesce"],"ingredients_en":["rice","cuttlefish","cuttlefish ink","white wine","fish stock"],"ingredients_fr":["riz","seiche","encre de seiche","vin blanc","bouillon de poisson"],"ingredients_es":["arroz","sepia","tinta de sepia","vino blanco","caldo de pescado"],"places":["Proto Fish Restaurant Dubrovnik","Lokanda Peskarija Dubrovnik","Orsan Yacht Club Restaurant Dubrovnik"]},
 {"name":"Šporki makaruli","name_en":"Dirty Macaroni","name_fr":"Macaronis en sauce ragusaine","name_es":"Macarrones sucios de Ragusa","description":"Pasta corta con un ragù scuro di manzo, vino rosso e spezie, chiamata “sporca” perché la salsa macchia ogni pezzo. Nasce come piatto della festa di San Biagio e richiede una cottura lenta per ottenere profondità senza pesantezza.","description_en":"Short pasta is coated in a dark beef, red-wine and spice ragù, called “dirty” because the sauce stains every piece. Traditionally linked to Saint Blaise's feast, it needs slow cooking for depth without heaviness.","description_fr":"Des pâtes courtes sont nappées d'un ragout sombre de bœuf, vin rouge et épices, dit «sale» car la sauce colore chaque morceau. Lié à la fête de saint Blaise, il exige une cuisson lente pour gagner en profondeur sans lourdeur.","description_es":"Pasta corta cubierta con un ragú oscuro de ternera, vino tinto y especias, llamado “sucio” porque la salsa mancha cada pieza. Vinculado a la fiesta de san Blas, requiere cocción lenta para ganar profundidad sin resultar pesado.","ingredients":["pasta","manzo","vino rosso","cipolla","spezie"],"ingredients_en":["pasta","beef","red wine","onion","spices"],"ingredients_fr":["pâtes","bœuf","vin rouge","oignon","épices"],"ingredients_es":["pasta","ternera","vino tinto","cebolla","especias"],"places":["Kopun Dubrovnik","Restaurant Mimoza Dubrovnik","Taj Mahal Old Town Dubrovnik"]},
 {"name":"Zelena menestra","name_en":"Dubrovnik Green Stew","name_fr":"Ragout vert de Dubrovnik","name_es":"Guiso verde de Dubrovnik","description":"Cavoli e verdure verdi cuociono con diversi tagli di maiale affumicato e salsiccia fino a formare uno stufato sostanzioso. È una preparazione invernale antica, legata più alle case e alle konobe tradizionali che alla cucina da spiaggia.","description_en":"Cabbage and leafy greens cook with several cuts of smoked pork and sausage into a substantial stew. This old winter preparation belongs more to homes and traditional konobas than to beachside cooking.","description_fr":"Choux et légumes verts mijotent avec plusieurs morceaux de porc fumé et de la saucisse pour former un ragout consistant. Cette ancienne préparation hivernale appartient davantage aux maisons et konobas traditionnelles qu'à la cuisine de plage.","description_es":"Coles y verduras verdes se cocinan con varios cortes de cerdo ahumado y salchicha hasta formar un guiso contundente. Esta antigua preparación invernal pertenece más a las casas y konobas tradicionales que a la cocina de playa.","ingredients":["cavolo","bietole","maiale affumicato","salsiccia","patate"],"ingredients_en":["cabbage","leafy greens","smoked pork","sausage","potatoes"],"ingredients_fr":["chou","légumes verts","porc fumé","saucisse","pommes de terre"],"ingredients_es":["col","verduras de hoja","cerdo ahumado","salchicha","patatas"],"places":["Kopun Dubrovnik","Konoba Dubrava Dubrovnik","Restaurant Mimoza Dubrovnik"]},
 {"name":"Dubrovačka rozata","name_en":"Dubrovnik Rozata","name_fr":"Rozata de Dubrovnik","name_es":"Rozata de Dubrovnik","description":"Crema cotta di uova, latte e zucchero profumata con liquore di rose e rovesciata su caramello. Ricorda un crème caramel, ma il rožulin le dà un aroma floreale riconoscibile e profondamente raguseo.","description_en":"An egg, milk and sugar custard scented with rose liqueur and turned out over caramel. It resembles crème caramel, but rožulin gives it a distinctive floral character rooted in Ragusa.","description_fr":"Crème cuite aux œufs, lait et sucre, parfumée à la liqueur de rose puis renversée sur un caramel. Elle rappelle une crème caramel, mais le rožulin lui donne un caractère floral propre à Raguse.","description_es":"Crema cocida de huevo, leche y azúcar aromatizada con licor de rosas y volcada sobre caramelo. Recuerda al flan, pero el rožulin le aporta un carácter floral profundamente raguseo.","ingredients":["uova","latte","zucchero","caramello","liquore di rose"],"ingredients_en":["eggs","milk","sugar","caramel","rose liqueur"],"ingredients_fr":["œufs","lait","sucre","caramel","liqueur de rose"],"ingredients_es":["huevos","leche","azúcar","caramelo","licor de rosas"],"places":["Proto Fish Restaurant Dubrovnik","Kopun Dubrovnik","Gradska Kavana Arsenal Dubrovnik"]},
 {"name":"Peka dalmata","name_en":"Dalmatian Peka","name_fr":"Peka dalmate","name_es":"Peka dálmata","description":"Carne o polpo con patate e verdure cuoce lentamente sotto una campana metallica coperta di brace. Va ordinata in anticipo: il valore del piatto sta nella cottura lunga, nei succhi concentrati e nella consistenza morbida.","description_en":"Meat or octopus with potatoes and vegetables cooks slowly beneath a metal bell covered in embers. It must be ordered ahead: its value lies in long cooking, concentrated juices and tender texture.","description_fr":"Viande ou poulpe, pommes de terre et légumes cuisent lentement sous une cloche métallique couverte de braises. À commander à l'avance: tout repose sur la cuisson longue, les jus concentrés et la tendreté.","description_es":"Carne o pulpo con patatas y verduras se cocina lentamente bajo una campana metálica cubierta de brasas. Debe encargarse con antelación: su valor está en la cocción larga, los jugos concentrados y la textura tierna.","ingredients":["agnello o polpo","patate","cipolla","verdure","olio d'oliva"],"ingredients_en":["lamb or octopus","potatoes","onion","vegetables","olive oil"],"ingredients_fr":["agneau ou poulpe","pommes de terre","oignon","légumes","huile d'olive"],"ingredients_es":["cordero o pulpo","patatas","cebolla","verduras","aceite de oliva"],"places":["Konoba Dubrava Dubrovnik","Restaurant Mimoza Dubrovnik","Konoba Bonaca Dubrovnik"]},
 {"name":"Salata od hobotnice","name_en":"Octopus Salad","name_fr":"Salade de poulpe","name_es":"Ensalada de pulpo","description":"Polpo lessato e tenero viene condito con patate, cipolla, prezzemolo, limone e olio d'oliva. È un antipasto adriatico semplice solo in apparenza: la qualità dipende dalla cottura precisa e dall'equilibrio dell'acidità.","description_en":"Tender boiled octopus is dressed with potatoes, onion, parsley, lemon and olive oil. This Adriatic starter only appears simple: quality depends on precise cooking and balanced acidity.","description_fr":"Le poulpe bouilli et tendre est assaisonné de pommes de terre, oignon, persil, citron et huile d'olive. Cette entrée adriatique n'est simple qu'en apparence: tout dépend de la cuisson et de l'équilibre acide.","description_es":"Pulpo cocido y tierno se aliña con patata, cebolla, perejil, limón y aceite de oliva. Este entrante adriático solo parece sencillo: la calidad depende de una cocción precisa y una acidez equilibrada.","ingredients":["polpo","patate","cipolla","prezzemolo","limone"],"ingredients_en":["octopus","potatoes","onion","parsley","lemon"],"ingredients_fr":["poulpe","pommes de terre","oignon","persil","citron"],"ingredients_es":["pulpo","patatas","cebolla","perejil","limón"],"places":["Lokanda Peskarija Dubrovnik","Proto Fish Restaurant Dubrovnik","Bota Sare Oyster & Sushi Bar Dubrovnik"]},
 {"name":"Stonske kamenice","name_en":"Ston Oysters","name_fr":"Huitres de Ston","name_es":"Ostras de Ston","description":"Le ostriche della baia di Mali Ston crescono in acque ricche di nutrienti e arrivano a Dubrovnik servite crude con limone o appena gratinate. Devono profumare di mare pulito e mantenere una consistenza soda e succosa.","description_en":"Oysters from Mali Ston Bay grow in nutrient-rich waters and reach Dubrovnik raw with lemon or lightly gratinated. They should smell of clean sea and retain a firm, juicy texture.","description_fr":"Les huitres de la baie de Mali Ston grandissent dans des eaux riches et arrivent à Dubrovnik crues avec citron ou légèrement gratinées. Elles doivent sentir la mer propre et garder une texture ferme et juteuse.","description_es":"Las ostras de la bahía de Mali Ston crecen en aguas ricas en nutrientes y llegan a Dubrovnik crudas con limón o ligeramente gratinadas. Deben oler a mar limpio y conservar una textura firme y jugosa.","ingredients":["ostriche di Ston","limone","ghiaccio"],"ingredients_en":["Ston oysters","lemon","ice"],"ingredients_fr":["huitres de Ston","citron","glace"],"ingredients_es":["ostras de Ston","limón","hielo"],"places":["Bota Sare Oyster & Sushi Bar Dubrovnik","Proto Fish Restaurant Dubrovnik","Restaurant 360 Dubrovnik"]},
 {"name":"Mantala","name_en":"Mantala Grape Dessert","name_fr":"Dessert au raisin Mantala","name_es":"Postre de uva Mantala","description":"Mosto d'uva concentrato viene addensato con semola, noci e spezie fino a ottenere un dolce compatto da tagliare. È una preparazione autunnale rara, legata alla vendemmia e alle dispense familiari del territorio di Konavle.","description_en":"Concentrated grape must is thickened with semolina, walnuts and spices into a firm sliced sweet. This rare autumn preparation is tied to the harvest and family pantries of the Konavle region.","description_fr":"Le mout de raisin concentré est épaissi avec semoule, noix et épices pour former un dessert ferme à trancher. Cette rare préparation automnale est liée aux vendanges et aux réserves familiales de Konavle.","description_es":"El mosto de uva concentrado se espesa con sémola, nueces y especias hasta formar un dulce firme que se corta en porciones. Esta rara preparación otoñal está ligada a la vendimia y las despensas familiares de Konavle.","ingredients":["mosto d'uva","semola","noci","cannella","chiodi di garofano"],"ingredients_en":["grape must","semolina","walnuts","cinnamon","cloves"],"ingredients_fr":["mout de raisin","semoule","noix","cannelle","clous de girofle"],"ingredients_es":["mosto de uva","sémola","nueces","canela","clavo"],"places":["Kopun Dubrovnik","Restaurant Sesame Dubrovnik","Gradska Kavana Arsenal Dubrovnik"]},
]


CULTURE_FACTS = [
 fact("⚓",n("Ragusa fu una repubblica marinara","Ragusa was a maritime republic","Raguse fut une république maritime","Ragusa fue una república marítima"),n("Diplomazia, commercio e una flotta mercantile permisero alla piccola repubblica di mantenere autonomia tra potenze maggiori.","Diplomacy, trade and a merchant fleet allowed the small republic to preserve autonomy among greater powers.","Diplomatie, commerce et flotte marchande permirent à la petite république de préserver son autonomie entre de grandes puissances.","La diplomacia, el comercio y una flota mercante permitieron a la pequeña república conservar su autonomía entre grandes potencias.")),
 fact("🧱",n("Le mura sono un sistema, non una semplice cinta","The walls are a system, not a simple ring","Les remparts forment un système complet","Las murallas forman un sistema completo"),n("Torri, forti, porte e difese sul mare furono adattati per secoli all'evoluzione delle armi.","Towers, forts, gates and sea defences were adapted for centuries to changing weapons.","Tours, forts, portes et défenses maritimes furent adaptés pendant des siècles à l'évolution des armes.","Torres, fortalezas, puertas y defensas marítimas se adaptaron durante siglos a la evolución de las armas.")),
 fact("🕊️",n("Libertas è la parola simbolo della città","Libertas is the city's symbolic word","Libertas est le mot symbole de la ville","Libertas es la palabra símbolo de la ciudad"),n("L'ideale di libertà politica della Repubblica compare ancora su bandiere, monumenti e cerimonie.","The Republic's ideal of political freedom still appears on flags, monuments and ceremonies.","L'idéal de liberté politique de la République figure encore sur drapeaux, monuments et cérémonies.","El ideal de libertad política de la República todavía aparece en banderas, monumentos y ceremonias.")),
 fact("💧",n("L'acquedotto cambiò la vita urbana","The aqueduct transformed urban life","L'aqueduc transforma la vie urbaine","El acueducto transformó la vida urbana"),n("Nel Quattrocento Onofrio della Cava portò acqua da chilometri di distanza fino alle fontane dentro le mura.","In the fifteenth century Onofrio della Cava brought water from kilometres away to fountains inside the walls.","Au XVe siècle, Onofrio della Cava amena l'eau de plusieurs kilomètres jusqu'aux fontaines intra-muros.","En el siglo XV, Onofrio della Cava llevó agua desde varios kilómetros hasta las fuentes dentro de las murallas.")),
 fact("🦠",n("Dubrovnik introdusse una quarantena precoce","Dubrovnik introduced an early quarantine","Dubrovnik instaura tôt la quarantaine","Dubrovnik implantó pronto la cuarentena"),n("Dal 1377 i viaggiatori provenienti da zone a rischio dovevano trascorrere un periodo isolati prima di entrare in città.","From 1377 travellers from affected areas had to spend a period in isolation before entering the city.","Dès 1377, les voyageurs venant de zones à risque devaient rester isolés avant d'entrer en ville.","Desde 1377, los viajeros procedentes de zonas de riesgo debían pasar un periodo aislados antes de entrar en la ciudad.")),
 fact("🏛️",n("Il terremoto del 1667 ridisegnò il centro","The 1667 earthquake reshaped the centre","Le séisme de 1667 remodela le centre","El terremoto de 1667 remodeló el centro"),n("La ricostruzione barocca diede maggiore uniformità alle facciate pur conservando l'impianto medievale.","Baroque rebuilding made façades more uniform while preserving the medieval street plan.","La reconstruction baroque uniformisa les façades tout en conservant le tracé médiéval.","La reconstrucción barroca dio mayor uniformidad a las fachadas conservando el trazado medieval.")),
 fact("🎭",n("La città diventa un palcoscenico estivo","The city becomes a summer stage","La ville devient une scène estivale","La ciudad se convierte en escenario estival"),n("Il Dubrovnik Summer Festival usa cortili, fortezze e piazze come scenografie per teatro e musica.","The Dubrovnik Summer Festival uses courtyards, fortresses and squares as settings for theatre and music.","Le Festival d'été de Dubrovnik utilise cours, forteresses et places comme décors de théâtre et de musique.","El Festival de Verano de Dubrovnik utiliza patios, fortalezas y plazas como escenarios de teatro y música.")),
 fact("⛵",n("Le isole fanno parte della città vissuta","The islands belong to everyday city life","Les îles appartiennent à la vie quotidienne","Las islas forman parte de la vida cotidiana"),n("Lokrum ed Elafiti non sono solo sfondo: traghetti, bagni e gite regolano il ritmo della costa.","Lokrum and the Elaphiti are not mere scenery: ferries, swimming and trips shape the coast's rhythm.","Lokrum et les Élaphites ne sont pas qu'un décor: ferries, baignades et excursions rythment la côte.","Lokrum y las Elafitas no son solo paisaje: ferris, baños y excursiones marcan el ritmo de la costa.")),
 fact("🕯️",n("San Biagio è il protettore di Dubrovnik","Saint Blaise protects Dubrovnik","Saint Blaise protège Dubrovnik","San Blas protege Dubrovnik"),n("La sua immagine appare sulle porte e sugli edifici, mentre la festa di febbraio coinvolge l'intera comunità.","His image appears on gates and buildings, while the February feast involves the whole community.","Son image figure sur portes et bâtiments, tandis que la fête de février mobilise toute la communauté.","Su imagen aparece en puertas y edificios, mientras la fiesta de febrero implica a toda la comunidad.")),
 fact("📜",n("Gli archivi conservano una memoria eccezionale","The archives preserve an exceptional record","Les archives conservent une mémoire exceptionnelle","Los archivos conservan una memoria excepcional"),n("Contratti, leggi e corrispondenza documentano secoli di commercio mediterraneo e amministrazione repubblicana.","Contracts, laws and correspondence document centuries of Mediterranean trade and republican administration.","Contrats, lois et correspondances documentent des siècles de commerce méditerranéen et d'administration républicaine.","Contratos, leyes y correspondencia documentan siglos de comercio mediterráneo y administración republicana.")),
 fact("🌿",n("La macchia mediterranea arriva dentro la visita","Mediterranean nature enters the visit","La nature méditerranéenne entre dans la visite","La naturaleza mediterránea entra en la visita"),n("Pini, agrumi, erbe aromatiche e rocce calcaree caratterizzano isole, parchi e cucina locale.","Pines, citrus, aromatic herbs and limestone shape the islands, parks and local cooking.","Pins, agrumes, herbes aromatiques et calcaire caractérisent îles, parcs et cuisine locale.","Pinos, cítricos, hierbas aromáticas y caliza caracterizan islas, parques y cocina local.")),
 fact("🕊️",n("La guerra del 1991 è memoria ancora vicina","The 1991 war remains a close memory","La guerre de 1991 reste une mémoire proche","La guerra de 1991 sigue siendo una memoria cercana"),n("L'assedio danneggiò il centro storico e segnò profondamente gli abitanti; musei e targhe ne raccontano l'impatto.","The siege damaged the old town and deeply marked residents; museums and plaques explain its impact.","Le siège endommagea la vieille ville et marqua profondément les habitants; musées et plaques en racontent l'impact.","El asedio dañó el casco antiguo y marcó profundamente a sus habitantes; museos y placas explican su impacto.")),
]


CITY_INFO={"city":CITY_ID,"currency":"Euro (€)","currency_en":"Euro (€)","currency_fr":"Euro (€)","currency_es":"Euro (€)","language":"Croato","language_en":"Croatian","language_fr":"Croate","language_es":"Croata","english_level":"alto","english_note":"L'inglese è molto diffuso nelle attività turistiche; alcune persone comprendono anche italiano.","english_note_en":"English is widely spoken in visitor businesses; some people also understand Italian.","english_note_fr":"L'anglais est très répandu dans les activités touristiques; certaines personnes comprennent aussi l'italien.","english_note_es":"El inglés está muy extendido en los servicios turísticos; algunas personas también comprenden italiano.","timezone":"CET (UTC+1), CEST (UTC+2) in estate","voltage":"230 V, prese tipo C e F","water":"L'acqua del rubinetto è potabile e generalmente di ottima qualità.","water_en":"Tap water is safe and generally of excellent quality.","water_fr":"L'eau du robinet est potable et généralement d'excellente qualité.","water_es":"El agua del grifo es potable y generalmente de excelente calidad.","tipping":"La mancia non è obbligatoria; nei ristoranti è comune lasciare circa il 5-10% per un buon servizio.","tipping_en":"Tipping is not required; leaving around 5-10% for good restaurant service is common.","tipping_fr":"Le pourboire n'est pas obligatoire; laisser environ 5 à 10% pour un bon service au restaurant est courant.","tipping_es":"La propina no es obligatoria; es habitual dejar alrededor del 5-10% por un buen servicio en restaurantes.","emergency_numbers":[{"label":"Emergenze generali","label_en":"General emergency","label_fr":"Urgences générales","label_es":"Emergencias generales","number":"112"},{"label":"Soccorso marittimo","label_en":"Maritime rescue","label_fr":"Secours maritime","label_es":"Salvamento marítimo","number":"195"}],"transport_apps":[{"name":"Libertas Dubrovnik","description":"Orari e informazioni della rete autobus urbana.","description_en":"Timetables and information for the city bus network.","description_fr":"Horaires et informations du réseau de bus urbain.","description_es":"Horarios e información de la red de autobuses urbanos.","ios_url":"https://www.libertasdubrovnik.hr/","android_url":"https://www.libertasdubrovnik.hr/"}],"useful_apps":[{"name":"Dubrovnik Pass","description":"Pass ufficiale per mura, musei e trasporto urbano incluso secondo la durata scelta.","description_en":"Official pass for walls, museums and included city transport according to duration.","description_fr":"Pass officiel pour remparts, musées et transports urbains inclus selon la durée.","description_es":"Pase oficial para murallas, museos y transporte urbano incluido según la duración.","ios_url":"https://dubrovnikpass.com/","android_url":"https://dubrovnikpass.com/"}],"quick_tips":["Visita le mura all'apertura o nel tardo pomeriggio per ridurre caldo e folla.","Controlla vento e mare prima di programmare Lokrum o altre isole.","Il centro storico è pedonale e presenta molte scale: usa scarpe con buona aderenza.","Confronta il Dubrovnik Pass con i singoli ingressi prima di acquistare.","Evita di trascinare valigie sulle scale del centro: verifica bene la posizione dell'alloggio."],"quick_tips_en":["Visit the walls at opening time or late afternoon to reduce heat and crowds.","Check wind and sea conditions before planning Lokrum or other islands.","The old town is pedestrian and has many stairs: wear shoes with good grip.","Compare the Dubrovnik Pass with separate admission prices before buying.","Avoid dragging luggage over old-town stairs: check your accommodation's exact location."],"quick_tips_fr":["Visitez les remparts à l'ouverture ou en fin d'après-midi pour limiter chaleur et foule.","Vérifiez vent et état de la mer avant de prévoir Lokrum ou d'autres îles.","La vieille ville est piétonne et compte beaucoup d'escaliers: portez des chaussures adhérentes.","Comparez le Dubrovnik Pass aux billets séparés avant l'achat.","Évitez de tirer des valises dans les escaliers: vérifiez précisément l'emplacement du logement."],"quick_tips_es":["Visita las murallas al abrir o al final de la tarde para reducir calor y multitudes.","Comprueba viento y estado del mar antes de planear Lokrum u otras islas.","El casco antiguo es peatonal y tiene muchas escaleras: usa calzado con buen agarre.","Compara el Dubrovnik Pass con las entradas individuales antes de comprar.","Evita arrastrar maletas por las escaleras: comprueba bien la ubicación del alojamiento."]}


NEIGHBORHOODS=[
 neighborhood(1,CITY_ID,n("Centro storico","Old Town","Vieille ville","Casco antiguo"),n("Pro: monumenti e atmosfera serale immediatamente accessibili. Pro: nessun mezzo necessario per il centro. Contro: prezzi alti e forte affollamento. Contro: molte scale, rumore e accesso difficile con bagagli.","Pros: immediate access to monuments and evening atmosphere. Pros: no transport needed within the centre. Cons: high prices and heavy crowds. Cons: many stairs, noise and difficult luggage access.","Avantages: monuments et ambiance du soir immédiatement accessibles. Avantages: aucun transport nécessaire dans le centre. Inconvénients: prix élevés et forte affluence. Inconvénients: nombreux escaliers, bruit et accès difficile avec bagages.","Ventajas: monumentos y ambiente nocturno inmediatos. Ventajas: no hace falta transporte dentro del centro. Desventajas: precios altos y mucha gente. Desventajas: numerosas escaleras, ruido y acceso difícil con equipaje."),["centro storico","attrazioni","turistico"]),
 neighborhood(2,CITY_ID,n("Pile","Pile","Pile","Pile"),n("Pro: accesso diretto alle mura e terminal autobus vicino. Pro: comodo con bagagli rispetto all'interno delle mura. Contro: traffico turistico intenso. Contro: alloggi e ristoranti costosi.","Pros: direct wall access and nearby bus terminal. Pros: easier with luggage than inside the walls. Cons: intense visitor traffic. Cons: expensive lodging and dining.","Avantages: accès direct aux remparts et terminal de bus proche. Avantages: plus pratique avec des bagages que l'intérieur des murs. Inconvénients: flux touristique intense. Inconvénients: hébergements et restaurants chers.","Ventajas: acceso directo a las murallas y terminal de autobuses cercano. Ventajas: más cómodo con equipaje que dentro de las murallas. Desventajas: tráfico turístico intenso. Desventajas: alojamiento y restaurantes caros."),["centrale","trasporti","turistico"]),
 neighborhood(3,CITY_ID,n("Ploče","Ploče","Ploče","Ploče"),n("Pro: viste spettacolari e vicinanza a Banje e porta orientale. Pro: ambiente più tranquillo del centro. Contro: numerose salite e scale. Contro: tariffe spesso elevate per la vista.","Pros: spectacular views and proximity to Banje and the eastern gate. Pros: calmer than the old town. Cons: many climbs and stairs. Cons: views often bring higher prices.","Avantages: vues spectaculaires et proximité de Banje et de la porte orientale. Avantages: plus calme que le centre. Inconvénients: nombreuses montées et marches. Inconvénients: tarifs souvent élevés pour la vue.","Ventajas: vistas espectaculares y cercanía a Banje y la puerta oriental. Ventajas: más tranquilo que el centro. Desventajas: muchas cuestas y escaleras. Desventajas: precios a menudo elevados por las vistas."),["panorama","spiaggia","tranquillo"]),
 neighborhood(4,CITY_ID,n("Gruž","Gruž","Gruž","Gruž"),n("Pro: porto, mercato e stazione autobus rendono facili arrivi ed escursioni. Pro: prezzi più accessibili e vita locale. Contro: serve il bus per il centro storico. Contro: paesaggio più portuale e trafficato.","Pros: harbour, market and bus station simplify arrivals and trips. Pros: better prices and local life. Cons: a bus is needed for the old town. Cons: the setting is more port-oriented and busy.","Avantages: port, marché et gare routière facilitent arrivées et excursions. Avantages: prix plus accessibles et vie locale. Inconvénients: bus nécessaire pour la vieille ville. Inconvénients: cadre plus portuaire et animé.","Ventajas: puerto, mercado y estación de autobuses facilitan llegadas y excursiones. Ventajas: precios más asequibles y vida local. Desventajas: se necesita autobús para el casco antiguo. Desventajas: entorno más portuario y transitado."),["porto","trasporti","locale"]),
 neighborhood(5,CITY_ID,n("Lapad","Lapad","Lapad","Lapad"),n("Pro: spiagge, passeggiate e ampia scelta di ristoranti. Pro: adatta a soggiorni più lunghi e famiglie. Contro: il centro richiede autobus o taxi. Contro: atmosfera meno storica.","Pros: beaches, walks and a broad restaurant choice. Pros: suitable for longer stays and families. Cons: the old town requires bus or taxi. Cons: less historic atmosphere.","Avantages: plages, promenades et large choix de restaurants. Avantages: adapté aux longs séjours et aux familles. Inconvénients: bus ou taxi nécessaire pour le centre. Inconvénients: ambiance moins historique.","Ventajas: playas, paseos y amplia oferta de restaurantes. Ventajas: adecuada para estancias largas y familias. Desventajas: el centro requiere autobús o taxi. Desventajas: ambiente menos histórico."),["spiaggia","famiglie","ristoranti"]),
 neighborhood(6,CITY_ID,n("Babin Kuk","Babin Kuk","Babin Kuk","Babin Kuk"),n("Pro: resort, spiagge e maggiore tranquillità. Pro: buoni servizi per famiglie e relax. Contro: è la zona più lontana dalle mura. Contro: esperienza meno locale e maggiore dipendenza dai mezzi.","Pros: resorts, beaches and greater quiet. Pros: strong family and leisure facilities. Cons: it is the farthest area from the walls. Cons: less local experience and greater transport dependence.","Avantages: resorts, plages et plus grande tranquillité. Avantages: bons services pour familles et détente. Inconvénients: secteur le plus éloigné des remparts. Inconvénients: expérience moins locale et dépendance accrue aux transports.","Ventajas: complejos, playas y mayor tranquilidad. Ventajas: buenos servicios para familias y descanso. Desventajas: es la zona más alejada de las murallas. Desventajas: experiencia menos local y mayor dependencia del transporte."),["resort","spiaggia","tranquillo"]),
]
